"""Train a CPU event classifier from four weakly labelled videos, no cash or new SAM run."""
import base64,datetime,hashlib,html,json
from pathlib import Path
import numpy as np
from run_ollama_trial import ROOT,write_json
from scene_mvp.object_event_model import SPEC,extract,fit,predict

CASES=[
 {'id':'X-15','trial':'sam2-object-20261017-235331-826825','kind':'bag','label':1,'label_source':'human_event_review','review':'object-review-20261017-235553-092545/human-event-review.accepted.local.json','review_field':'human_object_left_during_departure','statement':None},
 {'id':'X-16','trial':'sam2-object-20261017-233508-008975','kind':'bag','label':0,'label_source':'weak_organizer_normal_clip_label','review':'object-review-20261017-233721-280240/human-mask-review.accepted.local.json','review_field':None,'statement':None},
 {'id':'X-24','trial':'sam2-object-20261017-233416-615940','kind':'documents','label':1,'label_source':'human_conversation_event_statement_plus_mask_review','review':'object-review-20261017-233721-280240/human-mask-review.accepted.local.json','review_field':None,'statement':'в х24 на 8 секунде не спрятала важные документы и вещи в место хранения и вышла из кабинета'},
 {'id':'X-25','trial':'sam2-object-20261017-234451-410641','kind':'documents','label':0,'label_source':'human_removed_before_departure_plus_weak_organizer_normal_clip_label','review':'object-review-20261017-234849-977426/human-control-review.accepted.local.json','review_field':'human_object_removed_before_departure','statement':None},
]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def matrix(case):return [w['feature'] for w in case['features']['windows']]
def validation(cases,folds):
    results=[]
    for train_ids,test_ids in folds:
        train=[cases[i] for i in train_ids];model=fit([matrix(c) for c in train],[c['label'] for c in train])
        for i in test_ids:
            case=cases[i];prediction=predict(model,case['features']);answer=prediction['prediction'];binary=None if answer is None else int(answer=='object_left_pattern');results.append({'test_video':case['id'],'source_video_sha256':case['sha256'],'train_videos':[c['id'] for c in train],'train_video_sha256':[c['sha256'] for c in train],'expected_weak_video_label':case['label'],'predicted_label':binary,'correct':binary==case['label'],'prediction':prediction})
    return results

def main():
    out=ROOT/'local'/('object-event-training-'+datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d-%H%M%S-%f'));out.mkdir();write_json(out/'status.json',{'status':'running','cash_included':False})
    annotation_file=ROOT/'outputs/forte_annotations_draft.json';annotations=json.loads(annotation_file.read_text());lookup={v['content_group']:v for v in annotations['videos']};protocol={'feature_spec':SPEC,'model':'nonnegative L2 logistic multiple-instance classifier with smooth-max video pooling','training_unit':'video','folds':'leave_one_video_sha256_out','secondary_check':'leave_one_object_kind_out','hyperparameter_search':False,'evaluation_is_development_only':True,'independent_external_test':False,'cash_excluded':True,'model_trains_sam':False,'frame_labels_invented':False,'legal_labels_created':False,'source_annotations_sha256':sha(annotation_file),'cases':CASES,'code_sha256':{'trainer':sha(Path(__file__)),'model':sha(ROOT/'scene_mvp/object_event_model.py')}};write_json(out/'protocol.local.json',protocol)
    cases=[];seen=set()
    for definition in CASES:
        folder=ROOT/'local'/definition['trial'];observations_path=folder/'observations.local.json';calibration_path=folder/'calibration.local.json';profile=json.loads(calibration_path.read_text());observations=json.loads(observations_path.read_text());session_path=ROOT/'local'/profile['source_session']/'session.local.json';session=json.loads(session_path.read_text());group=lookup[definition['id']]
        if profile['target_object_kind']!=definition['kind'] or profile['source_video_sha256']!=session['source_video_sha256'] or group['sha256']!=profile['source_video_sha256'] or group['sha256'] in seen:raise ValueError('Object kind/video group mismatch')
        seen.add(group['sha256']);review_path=ROOT/'local'/definition['review'];review=json.loads(review_path.read_text());accepted=[c for c in review['cases'] if c['report_folder']==definition['trial'] and c['source_video_sha256']==group['sha256']]
        if len(accepted)!=1 or accepted[0]['human_mask_review']!='correct_on_selected_frames':raise ValueError('Expected accepted human mask review')
        if definition['review_field'] and accepted[0].get(definition['review_field'])!='yes':raise ValueError('Expected human event/context label')
        if definition['label']==0 and not any(a['label']=='без нарушения' for a in group['source_annotations']):raise ValueError('Negative case lacks organizer normal label')
        if sha(Path(session['source_video']))!=group['sha256']:raise ValueError('Source video bytes changed')
        features=extract(observations,profile)
        if not features['usable']:raise ValueError('Insufficient observations for training case '+definition['id'])
        case={**definition,'sha256':group['sha256'],'source_session':session['session_id'],'features':features,'profile':profile,'session':session,'observation_sha256':sha(observations_path),'calibration_sha256':sha(calibration_path),'review_sha256':sha(review_path)};cases.append(case)
    dataset=[{k:v for k,v in c.items() if k not in ('profile','session')} for c in cases];write_json(out/'dataset.local.json',{'label_unit':'video','videos':dataset,'cash_excluded':True,'no_prediction_labels_used':True})
    primary=validation(cases,[([j for j in range(len(cases)) if j!=i],[i]) for i in range(len(cases))]);secondary=validation(cases,[([i for i,c in enumerate(cases) if c['kind']!=kind],[i for i,c in enumerate(cases) if c['kind']==kind]) for kind in ('bag','documents')])
    final=fit([matrix(c) for c in cases],[c['label'] for c in cases]);np.savez_compressed(out/'object-event-model.npz',**final)
    cv={'unit':'video_not_frame','evaluation_scope':'development_grouped_cross_validation_not_external_test','leave_one_video_out':primary,'leave_one_kind_out':secondary,'primary_correct':sum(r['correct'] for r in primary),'primary_total':len(primary),'primary_false_positive':sum(r['expected_weak_video_label']==0 and r['predicted_label']==1 for r in primary),'primary_false_negative':sum(r['expected_weak_video_label']==1 and r['predicted_label']==0 for r in primary),'kind_correct':sum(r['correct'] for r in secondary),'kind_total':len(secondary)};write_json(out/'validation.local.json',cv)
    metadata={'schema_version':'object-event-model/1','model_file':'object-event-model.npz','model_sha256':sha(out/'object-event-model.npz'),'feature_spec':SPEC,'supported_object_kinds':['bag','documents'],'source_video_sha256':[c['sha256'] for c in cases],'training_videos':4,'positive_videos':2,'negative_videos':2,'weak_video_supervision':True,'frames_are_not_independent_examples':True,'model_trained_here':True,'sam_retrained':False,'requires_human_object_seed_and_role_geometry':True,'automatic_object_type_classification':False,'online_causality_validated':False,'localization_is_weak_proposal':True,'cash_supported':False,'approved_for_rule_engine':False,'legal_verdict':False,'independent_external_test':False};write_json(out/'model-metadata.local.json',metadata)
    summaries=[];cards=[]
    for c,row in zip(cases,primary):
        prediction=row['prediction'];best=prediction.get('strongest_window');summaries.append({'video':c['id'],'kind':c['kind'],'weak_label':c['label'],'frames':c['features']['total_frames'],'windows':len(c['features']['windows']),'coverage':c['features']['joint_observed_coverage'],'out_of_video_score':prediction['video_risk_score'],'predicted_label':row['predicted_label']})
        evidence=''
        if best:
            for t in best['evidence_times_sec']:
                f=min(c['session']['frames'],key=lambda f:abs(f['timestamp_sec']-t));path=ROOT/'local'/c['source_session']/f['file'];uri='data:image/jpeg;base64,'+base64.b64encode(path.read_bytes()).decode();evidence+='<figure><img src="'+uri+'"><figcaption>'+f"{t:.3f} с"+'</figcaption></figure>'
        expected='Предмет оставлен' if c['label'] else 'Отрицательный пример';pred='Риск оставленного предмета' if row['predicted_label']==1 else 'Риск не обнаружен' if row['predicted_label']==0 else 'Недостаточно наблюдений'
        cards.append('<section><h2>'+c['id']+' · '+('Сумка' if c['kind']=='bag' else 'Документы')+'</h2><p>Метка ролика: '+expected+'. Предсказание без обучения на этом видео: '+pred+'. Score: '+f"{prediction['video_risk_score']:.3f}"+'.</p><p>Обучение: '+html.escape(', '.join(row['train_videos']))+'. Ниже — окно с наибольшим модельным баллом; точные границы события не размечены.</p><div class="grid">'+evidence+'</div></section>')
    write_json(out/'summary.local.json',{'videos':summaries,'primary_correct':cv['primary_correct'],'primary_total':cv['primary_total'],'kind_correct':cv['kind_correct'],'kind_total':cv['kind_total'],'cash_excluded':True,'model_trained_here':True,'sam_retrained':False})
    table=''.join('<tr><td>'+r['video']+'</td><td>'+str(r['weak_label'])+'</td><td>'+str(r['predicted_label'])+'</td><td>'+f"{r['out_of_video_score']:.3f}"+'</td><td>'+str(r['frames'])+'</td><td>'+str(r['windows'])+'</td></tr>' for r in summaries)
    page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'"><title>Обучение: сумка и документы</title><style>body{font:18px system-ui;max-width:1250px;margin:30px auto;padding:18px}aside{background:#fff0ce;padding:18px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}figure{margin:0}img{width:100%}table{border-collapse:collapse}td,th{padding:10px;border:1px solid #bbb}section{margin-top:35px}</style><h1>Первая обученная модель: сумка и документы</h1><p>Обучен небольшой классификатор события на сохранённых масках SAM и геометрии кассира. SAM не переобучался. Деньги исключены. Модель обучается по меткам целого видео: положительный ролик может содержать короткий эпизод риска, его кадры не получают автоматически положительные метки.</p><aside>Всего 4 разных видео: 2 положительных и 2 отрицательных. Ручная проверка масок охватывала выбранные кадры. Часть меток — слабые метки организатора «без нарушения»; они не являются подробной разметкой каждого события. Это проверка разработки, а не независимый внешний тест. Результат не устанавливает юридическое нарушение и не подтверждает общую надёжность.</aside><h2>Проверка с исключением целого видео</h2><p>Совпадений: '''+str(cv['primary_correct'])+'/'+str(cv['primary_total'])+'. Ложных положительных: '+str(cv['primary_false_positive'])+'. Пропущенных положительных: '+str(cv['primary_false_negative'])+'.</p><p>Дополнительная проверка: обучение на сумке → проверка на документах и наоборот: '+str(cv['kind_correct'])+'/'+str(cv['kind_total'])+'. Настройки не подбирались по этим результатам. Итоговый файл модели отдельно обучен на всех четырёх роликах.</p><p>Score — внутренний балл, не калиброванная вероятность. Тип предмета, начальная подсказка и роль кассира задавались человеком; автоматическое распознавание этих входов не обучалось.</p><table><tr><th>Видео</th><th>Метка</th><th>Предсказание</th><th>Score</th><th>Кадры</th><th>Окна</th></tr>'+table+'</table>'+''.join(cards)+'</html>'
    (out/'report.html').write_text(page,encoding='utf-8');(out/'README.txt').write_text('Экспериментальная модель object_left_during_cashier_departure.\nSAM и тип предмета не обучались. Поддерживаются bag и documents; cash отложен.\nВход: observations.local.json + подтверждённая calibration.local.json от существующего SAM-процесса.\nОбучающие единицы — 4 видео (2 положительных, 2 отрицательных), а не все кадры как независимые примеры.\nИсточники слабых меток и SHA-256 приведены в dataset.local.json.\nИтоговая модель обучена на всех 4 видео; только validation.local.json содержит предсказания без обучения на проверяемом видео.\nНужны новые положительные и отрицательные ролики. Модель возвращает экспериментальный риск, а не юридический вердикт.\n',encoding='utf-8');write_json(out/'status.json',{'status':'completed','model_trained_here':True,'sam_retrained':False,'cash_excluded':True,'training_videos':4,'approved_for_rule_engine':False});print('OBJECT_EVENT_MODEL_READY:',out);print(json.dumps({k:cv[k] for k in ('primary_correct','primary_total','primary_false_positive','primary_false_negative','kind_correct','kind_total')}))

if __name__=='__main__':main()
